  }catch{return json({error:controller.signal.aborted?'生成が時間切れになりました。自動再試行はしません。':'生成結果を検証できませんでした。自動再試行はしません。'},502);}
  finally{
    clearTimeout(timer);
    try{await env.DB.prepare('UPDATE gpt_requests SET status = ?, input_tokens = ?, output_tokens = ? WHERE id = ?').bind(status,usage?.input_tokens||0,usage?.output_tokens||0,requestId).run();}catch{/* Reservation remains counted; no sensitive data is logged. */}
  }
}

