const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const root=path.resolve(__dirname,'..');
const files=[];
function add(name,asset=false){
  const bytes=fs.readFileSync(path.join(root,name));
  const entry={path:name,sha256:crypto.createHash('sha256').update(bytes).digest('hex')};
  if(asset)entry.asset=name.slice(7);else entry.text=bytes.toString('utf8');
  files.push(entry);
}
function walk(name,asset=false){
  for(const entry of fs.readdirSync(path.join(root,name),{withFileTypes:true}).sort((a,b)=>a.name.localeCompare(b.name,'en'))){
    if(entry.name.startsWith('.')||entry.name==='handoff-source.json')continue;
    const file=name+'/'+entry.name;
    if(entry.isDirectory())walk(file,asset);
    else if(entry.isFile()){
      // Export only authored source and known image formats, never local credentials.
      if(!/\.(?:js|cjs|mjs|py|html|css|json|sql|svg|png|jpe?g)$/.test(file))throw new Error('Unexpected handoff file: '+file);
      if(asset||/\.(?:png|jpe?g)$/.test(file)){
        if(!asset){files.push({path:file,base64:fs.readFileSync(path.join(root,file)).toString('base64')});continue;}
        add(file,true);
      }else add(file);
    }
  }
}
for(const name of ['public','worker','db','drizzle','scripts','tests'])walk(name,name==='public');
for(const name of ['package.json','package-lock.json','drizzle.config.js','seasonal-coverage.json','CLAUDE.md','CLAUDE_START.txt','HANDOFF_README.md','NAMING_VALIDATION.md','SEASONAL_VALIDATION.md','.env.example','.gitignore','.openai/hosting.json'])add(name);
