const {test}=require('node:test');
const assert=require('node:assert/strict');
const fs=require('node:fs'),path=require('node:path'),cp=require('node:child_process');
const T=require('../public/core.js'),H=require('../public/handoff.js');
const root=path.resolve(__dirname,'..');
cp.execFileSync(process.execPath,[path.join(root,'scripts/prepare-handoff.cjs')]);
const manifest=JSON.parse(fs.readFileSync(path.join(root,'public/handoff-source.json'),'utf8'));
const fetcher=async url=>{
  const file=path.join(root,'public',url);
  return fs.existsSync(file)?new Response(fs.readFileSync(file)):new Response('missing',{status:404});
};
function unzipStore(bytes){
  const files=new Map();let offset=0;
  while(bytes.readUInt32LE(offset)===0x04034b50){
    assert.equal(bytes.readUInt16LE(offset+6),0x800);assert.equal(bytes.readUInt16LE(offset+8),0);
    const size=bytes.readUInt32LE(offset+18),nameSize=bytes.readUInt16LE(offset+26),extraSize=bytes.readUInt16LE(offset+28);
    const name=bytes.subarray(offset+30,offset+30+nameSize).toString('utf8'),start=offset+30+nameSize+extraSize;
    files.set(name,bytes.subarray(start,start+size));offset=start+size;
  }
  assert.equal(bytes.readUInt32LE(offset),0x02014b50);
  const end=bytes.length-22;assert.equal(bytes.readUInt32LE(end),0x06054b50);
  assert.equal(bytes.readUInt32LE(end+16),offset);assert.equal(bytes.readUInt16LE(end+10),files.size);
  return files;
}
test('portable ZIP preserves UTF-8 paths and arbitrary binary bytes with a standard CRC',async()=>{
  assert.equal(H.crc32(new TextEncoder().encode('123456789')),0xcbf43926);
  const bytes=Uint8Array.from([0,255,128,1,2]);
  const files=unzipStore(Buffer.from(await H.zip([{path:'画像/テスト.png',data:bytes},{path:'.openai/hosting.json',data:'{}'}]).arrayBuffer()));
  assert.deepEqual(files.get('画像/テスト.png'),Buffer.from(bytes));assert.equal(files.get('.openai/hosting.json').toString(),'{}');
  for(const path of ['../secret','/absolute','a/../b','a\\b','https://outside.test','a?b','a\x00b'])assert.throws(()=>H.zip([{path,data:'x'}]));
  assert.throws(()=>H.zip([{path:'a',data:'1'},{path:'a',data:'2'}]));
});
test('handoff contains runnable source, binary fixtures, original artwork and exact saved backup; no credentials or runtime files',async()=>{
  const p={...T.blank(),name:'引き継ぎ用パン',beforeTax:'190',events:['秋'],allergyStatus:'unknown'};
  const backup=T.serialize([p],[p.id,p.id],{scale:0.95,cutMarks:false});let progress=0;
  const files=unzipStore(Buffer.from(await H.createPackage({backup,fetcher,onProgress:n=>{progress=n;}}).then(x=>x.arrayBuffer())));
  assert.equal(progress,manifest.files.length);
  for(const name of ['public/index.html','public/archive.js','worker/generate.mjs','CLAUDE.md','HANDOFF_README.md','CLAUDE_START.txt','scripts/prepare-handoff.cjs','tests/fixtures/photo.jpg','.openai/hosting.json'])assert.ok(files.has(name),name);
  assert.equal(files.get('data/TERRAS-backup.json').toString(),backup);assert.equal(T.parseBackup(files.get('data/TERRAS-backup.json').toString()).selection.length,2);
  for(const entry of manifest.files){
    if(entry.path==='README.md')continue;
    assert.deepEqual(files.get(entry.path),fs.readFileSync(path.join(root,entry.path)),entry.path);
  }
  const context={window:{}};require('node:vm').runInNewContext(fs.readFileSync(path.join(root,'public/season-data.js'),'utf8'),context);
  for(const name of context.window.TERRAS_SEASONS.originalImages)assert.ok(files.has('public/'+name));
  for(const name of files.keys())assert.ok(!/(^|\/)(?:\.git|node_modules|dist|\.env\.local|GPT_VALIDATION\.md|handoff-source\.json)(\/|$)/.test(name),name);
  assert.deepEqual(JSON.parse(files.get('handoff-metadata.json')).productCount,1);
});
test('source-only handoff makes absence of product data explicit',async()=>{
  const files=unzipStore(Buffer.from(await H.createPackage({fetcher}).then(x=>x.arrayBuffer())));
  assert.equal(files.has('data/TERRAS-backup.json'),false);
