  for(const change of [b=>b.photos.push({...b.photos[0]}),b=>b.photos[0].view='tray',b=>b.photos.splice(0,1),b=>b.quality.answers[0]=null,b=>b.photos[0].data='https://invalid.test',b=>b.count=4]){const b=request(),e=env();change(b);assert.equal((await handleAPI(req(b),e,{fetcher:async()=>{throw new Error('must not call');}})).status,400);assert.equal(e.sql.prepare('SELECT COUNT(*) AS n FROM gpt_requests').get().n,0);}
  const e=env();for(let i=0;i<10;i++)e.sql.prepare('INSERT INTO gpt_requests(id,created_at,status) VALUES(?,?,?)').run('legacy'+i,i,'completed');assert.equal((await handleAPI(req(request()),e,{fetcher:async()=>{throw new Error('must not call');}})).status,429);
});
test('AI optimistic overall cannot override a cross; missing mandatory photos cannot become passes',async()=>{const {handleAPI}=await import('../worker/generate.mjs'),e=env(),body=request();body.photos=body.photos.slice(0,1);const output=check();output.principles[0].mark='×';const r=await handleAPI(req(body),e,{fetcher:async()=>upstream({candidates:Array.from({length:3},candidate),check:output})});const data=await r.json();assert.equal(data.check.overall,'直してから');for(const i of [1,4,6])assert.equal(data.check.principles[i].mark,'写真では判定できない');});
test('legacy five-question settings migrate to photo advice while past reviews keep their original score and decision',()=>{
  const legacy=Q.blank();legacy.criteria.questions=['旧基準の焼き色','旧基準の中身','旧3','旧4','旧5'];
  legacy.baselines.shokupan=photo;legacy.proposer='保存済みスタッフ';
  legacy.reviews=[{id:'legacy-review',at:new Date().toISOString(),kind:'パン',proposer:'保存済みスタッフ',answers:[true,true,false,false,false],criteria:Q.clone(legacy.criteria),views:Q.VIEWS.slice(),check:check(),candidates:Array.from({length:3},candidate),decision:'OK',chosen:1,note:'当時の返事'}];
  legacy.basics=[Q.basic({id:'legacy-basic',at:new Date().toISOString(),product:'shokupan',scores:[3,3,2,2,2],cause:''})];
  const parsed=T.parseBackup(JSON.stringify({app:'TERRAS price cards',schemaVersion:1,products:[],selection:[],settings:{scale:1,cutMarks:true},quality:legacy})).quality;
  assert.deepEqual(parsed.criteria.questions,[]);
  assert.equal(parsed.reviews[0].answers.length,5);assert.equal(parsed.reviews[0].criteria.questions.length,5);assert.equal(parsed.reviews[0].check.overall,'直してから');assert.equal(parsed.reviews[0].decision,'OK');assert.equal(parsed.reviews[0].chosen,1);
  assert.ok(Q.shareText(parsed.reviews[0]).includes('5問チェック 2/5（旧基準）'));
  assert.equal(parsed.basics[0].total,12);assert.ok(parsed.baselines.shokupan);assert.equal(parsed.proposer,'保存済みスタッフ');
  const next=Q.qualityInput({mode:'advice',criteria:parsed.criteria},Q.PHOTO_VIEWS);assert.equal(next.answers.length,0);assert.equal(Q.assessment(check(),Q.PHOTO_VIEWS,next.answers,true).overall,'判定なし');
  assert.equal(Q.merge(parsed,parsed).reviews.length,1);
});
