test('photo-only advice needs no kind, materials, top photo or staff answers; one upstream call returns no invented names',async()=>{
  const {handleAPI}=await import('../worker/generate.mjs'),e=env();let calls=0,sent;
  const body={...request(),kind:'',materials:'',photos:[{view:'angle',data:photo}],quality:{mode:'advice',criteria:Q.DEFAULTS}};
  const r=await handleAPI(req(body),e,{fetcher:async(_,options)=>{calls++;sent=JSON.parse(options.body);return upstream({candidates:[],check:check()});}});
  assert.equal(r.status,200);const data=await r.json();assert.equal(calls,1);assert.deepEqual(data.candidates,[]);assert.equal(data.check.overall,'判定なし');
  assert.equal(sent.text.format.schema.properties.candidates.maxItems,0);assert.deepEqual(sent.text.format.schema.properties.check.properties.overall.enum,['判定なし']);
  const facts=JSON.parse(sent.input[0].content[0].text);assert.deepEqual(facts.staffAnswers,[]);assert.deepEqual(facts.criteria.questions,[]);assert.equal(facts.materials,'');assert.ok(sent.instructions.includes('写真から材料'));assert.equal(e.sql.prepare('SELECT COUNT(*) AS n FROM gpt_requests').get().n,1);
});
