test('advice is shared and backed up without questionnaires or approval claims; photo-only replies can have no name',()=>{
  const raw=check();raw.principles[0].reason='表面の焼き色がはっきり見えます。';raw.principles[2].mark='△';raw.principles[2].fix='主役の色が見えるよう、飾りを少し減らす。';
  const record=Q.review({id:'advice-only',at:new Date().toISOString(),mode:'advice',kind:'写真からの相談',proposer:'山田',criteria:Q.DEFAULTS,answers:[],views:['angle'],check:raw,candidates:[],decision:'OK',chosen:null,note:'そのまま進める'});
  const a=Q.photoAdvice(record.check,record.views);assert.ok(a.good.includes(raw.principles[0].reason));assert.ok(a.improve.includes(raw.principles[2].fix));assert.ok(a.next);assert.equal(record.check.overall,'判定なし');
  const message=Q.shareText(record);assert.ok(message.includes('良いところ'));assert.ok(message.includes('直すとよいところ'));assert.ok(!message.includes('問チェック'));assert.ok(!message.includes('社長に出せる'));assert.ok(!message.includes('名前案'));
  const state=Q.blank();state.reviews=[record];const restored=T.parseBackup(T.serialize([],[],{scale:1,cutMarks:true},state));assert.equal(restored.quality.reviews[0].mode,'advice');assert.equal(restored.quality.reviews[0].decision,'OK');assert.deepEqual(restored.quality.reviews[0].answers,[]);
  assert.deepEqual(Q.photoAdvice(record.check,[]).good,[]);
  const items=Q.adviceItems(record.check,record.views,record.criteria);assert.equal(items.good[0].title,Q.DEFAULTS.principles[0].title);assert.equal(items.improve[0].title,Q.DEFAULTS.principles[2].title);assert.equal(items.improve[0].mark,'△');
  assert.ok(message.includes('■ 良いところ\n・'+Q.DEFAULTS.principles[0].title+'：'));assert.ok(message.includes('（まずこれ）'));assert.ok(message.includes('気になる点をひと言'));
});
test('consult keeps entered price and cost, shows cost rate in LINE text, and rejects non-integer yen',()=>{
  const raw={principles:[1,2,3,4,5,6,7].map(no=>({no,mark:'○',reason:'見えています',fix:'このままで良いです'})),overall:'判定なし'};
  const base={id:'pc-1',at:new Date().toISOString(),mode:'advice',kind:'クロックムッシュ',proposer:'山田',criteria:Q.DEFAULTS,answers:[],views:['top'],check:raw,candidates:[],decision:'pending',chosen:null,note:''};
  const r=Q.review({...base,price:'380',cost:'120'});assert.equal(r.price,'380');assert.equal(r.cost,'120');
  assert.equal(Q.costLine(r),'売価 380円（税込）・原価 120円・原価率 31.6%');
  assert.ok(Q.shareText(r).split('\n')[2].startsWith('売価 380円'));
  assert.equal(Q.costLine(Q.review({...base,price:'380'})),'売価 380円（税込）・原価 未入力');
  const none=Q.review(base);assert.equal(none.price,undefined);assert.equal(Q.costLine(none),'');assert.ok(!Q.shareText(none).includes('売価'));
  assert.throws(()=>Q.review({...base,price:'380.5'}),/売価は円の整数/);assert.throws(()=>Q.review({...base,cost:'-1'}),/原価は円の整数/);
});

const {test}=require('node:test');
const assert=require('node:assert/strict');
const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm');
const T=require('../public/core.js');
const ctx={window:{}};vm.runInNewContext(fs.readFileSync(path.resolve(__dirname,'../public/archive.js'),'utf8'),ctx);vm.runInNewContext(fs.readFileSync(path.resolve(__dirname,'../public/season-data.js'),'utf8'),ctx);
const A=JSON.parse(JSON.stringify(ctx.window.TERRAS_ARCHIVE)),S=JSON.parse(JSON.stringify(ctx.window.TERRAS_SEASONS));
const valid=()=>({...T.blank(),name:'登録商品',beforeTax:'190'});
test('seven groups use exact source tab names, not ingredients',()=>{
 assert.equal(S.groups.length,7);assert.equal(S.stats.source_tabs,20);const halloween=S.groups.find(g=>g.label==='ハロウィン');
 assert.equal(T.seasonHistory(A.cards,halloween).length,6);assert.equal(halloween.occurrences,8);
 const unrelated={...A.cards[0],name_raw:'かぼちゃパン',sources:[{sheet_name:'通常商品'}]};assert.deepEqual(T.eventsForArchive(unrelated,S.groups),[]);
});
test('all 79 seasonal source occurrences have readable preview assets',()=>{
 let count=0;for(const c of A.cards)for(const src of c.sources){if(!S.groups.some(g=>g.sheets.includes(src.sheet_name)))continue;const file=S.previews[String(src.sheet_index)].cards[c.id+'@'+src.name_cell];assert.ok(file);assert.ok(fs.existsSync(path.resolve(__dirname,'../public',file)));count++;}assert.equal(count,79);
});
test('Halloween source art is retained as five unmodified original files',()=>{
 assert.equal(S.originalImages.length,5);for(const file of S.originalImages){const bytes=fs.readFileSync(path.resolve(__dirname,'../public',file));assert.equal(bytes.subarray(0,8).toString('hex'),'89504e470d0a1a0a');}
 const svg=fs.readFileSync(path.resolve(__dirname,'../public/seasonal-source/card-0-C4.svg'),'utf8');assert.ok(svg.includes('data:image/png;base64,'));assert.ok(svg.includes('#CC00CC'));assert.ok(svg.includes('鴨とかぼちゃのタルティーヌ'));
});
test('season search and empty groups are safe',()=>{const g=S.groups[0];assert.equal(T.seasonHistory(A.cards,g,'存在しない検索語').length,0);assert.equal(T.seasonHistory(A.cards,{sheets:[]}).length,0);assert.equal(T.seasonHistory(A.cards,g,'鴨').length,1);});
test('events parse, validate, duplicate and round-trip without altering print data',()=>{
 const p={...valid(),events:T.parseEvents('ハロウィン、 秋限定,ハロウィン\n試作')};assert.deepEqual(p.events,['ハロウィン','秋限定','試作']);assert.deepEqual(T.validate(p),[]);
 const b=T.parseBackup(T.serialize([p],[p.id],{scale:1,cutMarks:true}));assert.deepEqual(b.products[0].events,p.events);assert.deepEqual(T.copy(p).events,p.events);assert.equal(b.products[0].beforeTax,'190');assert.equal(b.products[0].includingTax,'');
 assert.ok(T.validate({...p,events:['a'.repeat(41)]}).length);assert.ok(T.validate({...p,events:Array(11).fill('x')}).length);
});
test('legacy schema-1 records without events remain compatible and unchanged',()=>{
 const p=valid();delete p.events;const backup=T.serialize([p],[p.id,p.id],{scale:.95,cutMarks:false});const b=T.parseBackup(backup);assert.equal(b.schemaVersion,1);assert.equal(b.products[0].events,undefined);assert.equal(b.products[0].id,p.id);assert.equal(b.selection.length,2);assert.equal(T.mergeBackup([p],b.products).count,0);
});
test('seasonal history copy preserves source and keeps price/allergens unconfirmed',()=>{
 const c=T.seasonHistory(A.cards,S.groups[0])[0],p=T.fromArchive(c);p.events=['ハロウィン'];assert.equal(p.beforeTax,'');assert.equal(p.includingTax,'');assert.equal(p.allergyStatus,'unknown');assert.deepEqual(p.allergens,[]);assert.deepEqual(p.provenance,c);
});

